<?php
$id = (int)($_GET['id'] ?? 0);
$page_title = $id > 0 ? 'Editar ficha T-TI-F-08' : 'Nueva ficha T-TI-F-08';
require_once(__DIR__ . '/../../includes/load.php');
require_once(__DIR__ . '/../../config/app.php');
require_once(__DIR__ . '/funciones.php');
require_permiso('accesos_usuario', $id > 0 ? 'editar' : 'crear');
ensure_users_tipo_registro();
ensure_asig_maquina_schema();

$record = $id > 0 ? f08_get_record($id) : null;
if ($id > 0 && !$record) {
    $session->msg('d', 'La ficha solicitada no existe.');
    redirect('index.php', false);
}
$emailRows = $id > 0 ? find_by_sql("SELECT c.`id`,c.`asunto`,c.`descripcion`,c.`nombre_original`,c.`extension`,c.`tamano_bytes`,c.`estado`,
  DATE_FORMAT(c.`fecha_carga`,'%d/%m/%Y %H:%i') AS `fecha_carga`,u.`name` AS `cargado_por_nombre`
  FROM `usuariosf08_correos` c LEFT JOIN `users` u ON u.`id`=c.`cargado_por`
  WHERE c.`registro_id`={$id} ORDER BY c.`fecha_carga` DESC,c.`id` DESC") : [];
$preselectedUserId = $record ? (int)$record['user_id'] : max(0, (int)($_GET['user_id'] ?? 0));

$users = find_by_sql("SELECT `id`,`name`,`cargo`,`UserHomeTama`,`correo`,`telefono`,`area`,`subarea`,`status`,`estado`
  FROM `users`
  WHERE COALESCE(`tipo_registro`,'USUARIO')='USUARIO'
    AND `status`=1
    AND `estado`=1
  ORDER BY `name`");
$machines = find_by_sql("SELECT `IdMaquina`,`Host`,`Tipo_Activo`,`EstadoMaquina` FROM `maquina` ORDER BY `Host`");
$sapAccounts = find_by_sql("SELECT s.`IdUsuSap`,s.`UserId`,s.`UsuarioSap`,s.`CuentaTer`,s.`NompuSap`,s.`Estado`,
  COALESCE(t.`Licencia`,'') AS `Licencia`,COALESCE(t.`SuperUsuario`,'NO') AS `SuperUsuario`
  FROM `usuariossap` s
  LEFT JOIN `usuariotreminalsap` t ON t.`IdUsuTerminal`=(
    SELECT MAX(t2.`IdUsuTerminal`) FROM `usuariotreminalsap` t2 WHERE t2.`UsuTerminal`=s.`CuentaTer`
  )
  WHERE s.`UserId` IS NOT NULL
  ORDER BY s.`Estado` DESC,s.`UsuarioSap`");
$orbisAccounts = find_by_sql("SELECT o.`IdUsuOrbis`,u.`id` AS `UserId`,o.`CuentaOrbis`,o.`Utilidad`,o.`Estado`
  FROM `usuariosorbis` o
  INNER JOIN `users` u ON u.`id`=o.`UserId` OR (o.`UserId` IS NULL AND TRIM(LOWER(u.`name`))=TRIM(LOWER(o.`NomUsuario`)))
  WHERE o.`IdUsuOrbis`>0
  ORDER BY o.`Estado` DESC,o.`CuentaOrbis`");
$assignments = find_by_sql("SELECT a.`id` AS user_id,a.`IdMaquina`,m.`Host`
  FROM `asig_maquina` a INNER JOIN `maquina` m ON m.`IdMaquina`=a.`IdMaquina`
  WHERE a.`Estado`=1 ORDER BY a.`IdAsMaq` DESC");
$assignmentMap = [];
foreach ($assignments as $assignment) {
    $uid = (int)$assignment['user_id'];
    if (!isset($assignmentMap[$uid])) {
        $assignmentMap[$uid] = ['machine_id' => (int)$assignment['IdMaquina'], 'host' => $assignment['Host']];
    }
}
$userMap = [];
foreach ($users as $user) {
    $uid = (int)$user['id'];
    $userMap[$uid] = [
        'name' => $user['name'], 'cargo' => $user['cargo'], 'samba' => $user['UserHomeTama'],
        'correo' => $user['correo'], 'telefono' => $user['telefono'], 'area' => $user['area'],
        'subarea' => $user['subarea'], 'active' => (int)$user['status'] === 1 && (int)$user['estado'] === 1,
        'machine_id' => $assignmentMap[$uid]['machine_id'] ?? null,
        'host' => $assignmentMap[$uid]['host'] ?? '',
    ];
}

$value = function(string $field, $default = '') use ($record) {
    return $record !== null && array_key_exists($field, $record) ? $record[$field] : $default;
};
$yes = function(string $field, string $default = 'NO') use ($value): string {
    return f08_yes($value($field, $default)) ? 'SI' : 'NO';
};
$extraCss = [
    'https://fonts.googleapis.com/css2?family=Manrope:wght@500;600;700;800&display=swap',
    'https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css',
    'https://cdn.jsdelivr.net/npm/@ttskch/select2-bootstrap4-theme@1.5.2/dist/select2-bootstrap4.min.css',
];
$userMapJson = json_encode($userMap, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
$sapAccountsJson = json_encode(array_map(static function(array $account): array {
    return [
        'id' => (int)$account['IdUsuSap'],
        'user_id' => (int)$account['UserId'],
        'usuario' => (string)$account['UsuarioSap'],
        'terminal' => (string)$account['CuentaTer'],
        'licencia' => (string)$account['Licencia'],
        'perfil' => (string)$account['NompuSap'],
        'superusuario' => (string)$account['SuperUsuario'],
        'active' => (int)$account['Estado'] === 1,
    ];
}, $sapAccounts), JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
$orbisAccountsJson = json_encode(array_map(static function(array $account): array {
    return [
        'id' => (int)$account['IdUsuOrbis'],
        'user_id' => (int)$account['UserId'],
        'usuario' => (string)$account['CuentaOrbis'],
        'utilidad' => (string)$account['Utilidad'],
        'active' => (int)$account['Estado'] === 1,
    ];
}, $orbisAccounts), JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
$sambaCatalog = f08_samba_catalog();
$sambaLabels = f08_samba_labels();
$sambaWriteStored = (string)$value('CarpetasCompartidasM');
$sambaReadStored = (string)$value('CarpetasCompartidasV');
$sambaCustomWrite = f08_samba_custom_value($sambaWriteStored, $sambaCatalog);
$sambaCustomRead = f08_samba_custom_value($sambaReadStored, $sambaCatalog);
$positions = f08_get_positions(true);
$selectedPositionId = (int)$value('puesto_id');
if ($selectedPositionId === 0 && trim((string)$value('Cargo')) !== '') {
    $recordPositionKey = f08_position_key((string)$value('Cargo'));
    foreach ($positions as $position) if ((string)$position['nombre_clave'] === $recordPositionKey) $selectedPositionId = (int)$position['id'];
}
$positionTemplates = [];
foreach ($positions as $position) {
    $template = ['id' => (int)$position['id'], 'name' => (string)$position['nombre'], 'key' => (string)$position['nombre_clave'], 'ready' => (int)$position['configurado'] === 1];
    foreach (f08_template_fields() as $field) $template[$field] = (string)($position[$field] ?? '');
    $positionTemplates[] = $template;
}
$positionTemplatesJson = json_encode($positionTemplates, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
include_once(__DIR__ . '/../../layouts/header.php');
?>
