 function renderEmails(rows){f08EmailRows=rows||[];$('#f08MailCount').text(f08EmailRows.length+' archivo(s)');var list=$('#f08MailList');if(!list.length)return;if(!f08EmailRows.length){list.html('<div class="f08-mail-empty"><div><i class="far fa-envelope-open fa-2x mb-2 d-block"></i>A&uacute;n no hay correos archivados en esta ficha.</div></div>');return}list.html(f08EmailRows.map(function(item){var active=item.estado==='VALIDO',title=item.asunto||item.nombre_original;return'<div class="f08-mail-item '+(active?'':'inactive')+'"><div class="f08-mail-icon"><i class="fas '+(item.extension==='pdf'?'fa-file-pdf':'fa-envelope')+'"></i></div><div class="f08-mail-info"><strong>'+mailEsc(title)+'</strong><span>'+mailEsc(item.nombre_original)+' &middot; '+mailSize(item.tamano_bytes)+'</span><span>'+mailEsc(item.fecha_carga)+' &middot; '+mailEsc(item.cargado_por_nombre||'Sistema')+'</span>'+(item.descripcion?'<span>'+mailEsc(item.descripcion)+'</span>':'')+'<span class="f08-mail-status">'+(active?'V&Aacute;LIDO':'INACTIVO')+'</span></div><div class="f08-mail-actions"><a class="btn btn-outline-info" target="_blank" href="correos.php?action=download&id='+Number(item.id)+'" title="Abrir o descargar"><i class="fas fa-external-link-alt"></i></a><button type="button" class="btn '+(active?'btn-outline-secondary':'btn-outline-success')+' btnMailStatus" data-id="'+Number(item.id)+'" data-status="'+(active?'INACTIVO':'VALIDO')+'" title="'+(active?'Marcar inactivo':'Marcar valido')+'"><i class="fas '+(active?'fa-archive':'fa-check')+'"></i></button></div></div>'}).join(''))}
