 function openMailPreview(id){var box=$('#f08MailPreviewContent'),download='correos.php?action=download&id='+id;$('#f08MailPreviewDownload').attr('href',download);$('#f08MailPreviewTitle').text('Cargando correo...');box.html('<div class="f08-mail-empty"><i class="fas fa-spinner fa-spin mr-1"></i>Interpretando el archivo...</div>');$('#modalF08MailPreview').modal('show');fetch('correos.php?action=preview&id='+encodeURIComponent(id),{credentials:'same-origin'}).then(function(response){return response.json().then(function(json){if(!response.ok)throw new Error(json.error||'No se pudo visualizar.');return json})}).then(function(data){if(data.type==='pdf'){$('#f08MailPreviewTitle').text('Documento PDF');box.html('<iframe class="f08-mail-preview-frame" src="'+mailEsc(data.url)+'"></iframe>');return}var mail=data.content||{};$('#f08MailPreviewTitle').text(mail.subject||'Correo archivado');box.html('<div class="f08-mail-preview-meta">'+mailPreviewPair('De',mail.sender)+mailPreviewPair('Para',mail.to)+mailPreviewPair('CC',mail.cc)+mailPreviewPair('Fecha',mail.date)+'<label>Adjuntos</label><strong>'+mailPreviewAttachments(mail.attachments||[])+'</strong></div><div class="f08-mail-preview-body">'+mailEsc(mail.body||'El correo no contiene texto visible.')+'</div>')}).catch(function(error){box.html('<div class="alert alert-danger mb-0">'+mailEsc(error.message)+'</div>')})}
