 function renderAclSummary(target,items){var box=$(target).empty();if(!items.length){box.append($('<span class="f08-acl-none-selected">Sin carpetas asignadas</span>'));return}items.forEach(function(item){box.append($('<span class="f08-acl-chip"></span>').text(f08SambaLabels[item]?item+' - '+f08SambaLabels[item]:item))})}
 function syncSamba(){var write=[],read=[];$('.f08-acl-folder').each(function(){var code=String($(this).data('code')),permission=$(this).attr('data-current');if(permission==='write')write.push(code);if(permission==='read')read.push(code)});var customWrite=customFolders($('#f08CustomWrite').val()),customRead=customFolders($('#f08CustomRead').val());var writeKeys={};write.concat(customWrite).forEach(function(item){writeKeys[item.toLowerCase()]=true});customRead=customRead.filter(function(item){return !writeKeys[item.toLowerCase()]});var allWrite=write.concat(customWrite),allRead=read.concat(customRead);$('#f08FoldersWrite').val(allWrite.join(', '));$('#f08FoldersRead').val(allRead.join(', '));$('#f08WriteCount').text(allWrite.length);$('#f08ReadCount').text(allRead.length);renderAclSummary('#f08WriteSummary',allWrite);renderAclSummary('#f08ReadSummary',allRead)}
