 function applyFolders(template){var write=templateFolders(template.CarpetasCompartidasM),read=templateFolders(template.CarpetasCompartidasV),writeKeys={},readKeys={};write.forEach(function(v){writeKeys[v.toLowerCase()]=true});read.forEach(function(v){readKeys[v.toLowerCase()]=true});$('.f08-acl-folder').each(function(){var row=$(this),key=String(row.data('code')).toLowerCase(),permission=writeKeys[key]?'write':(readKeys[key]?'read':'none');row.attr('data-current',permission);row.find('.f08-acl-option').removeClass('active').attr('aria-pressed','false').filter('[data-permission="'+permission+'"]').addClass('active').attr('aria-pressed','true');delete writeKeys[key];delete readKeys[key]});$('#f08CustomWrite').val(Object.keys(writeKeys).map(function(key){return write.find(function(v){return v.toLowerCase()===key})}).join(', '));$('#f08CustomRead').val(Object.keys(readKeys).map(function(key){return read.find(function(v){return v.toLowerCase()===key})}).join(', '));syncSamba();filterAcl()}
